-- fix/map_house.lua [HOUSE] House duel map (2026-10-28): a big two-storey modern suburban house, 1v1 / 2v2 / 3v3.
-- GENERATED by tools/house_lua.py from tools/house_installer.lua + notes/maps/house_layout.json. Never hand-edit this file:
-- edit the template or the layout (tools/house_layout.py) and regenerate. Plan + numbers: notes/house_plan.md; build log:
-- notes/house_build.md.
-- What it builds (match places only; refuses in the lobby, which gets the map through duel_split_map ONLY='House'):
--   Workspace.House (Indoor = true)
--     CollisionProxies  COLP_<part id>: every collision box of the layout (walls, sills, floors, ceilings, stairs = ramp wedges,
--                       railings' handrails, furniture), invisible; furniture low 3.4 / tall 8 = cover, everything else NotCover.
--                       BAR_<id>: player-only barriers (tag WindowBarrier: the breakable-glass code puts them in the
--                       "WindowBarrier" collision group = bodies only) in every window opening and along the gallery / stairs.
--                       PCOL_<id>: walk blockers under floor dressing (also WindowBarrier: bodies stop, bullets pass).
--     Shootables        <window id>: Model, attribute Shootable = "Glass", children Glass + BrokenGlass (the modeler's panes).
--     Doors             <door id>: Model, attributes DoorState ("Open" = held ajar, "Closed", "Locked"), Ajar, OpenDeg, Locked,
--                       ClosedCF / OpenCF (the Hinge's CFrame shut / ajar); Hinge (PrimaryPart, on the hinge line at the floor),
--                       Leaf (the collision proxy, NotCover), the leaf mesh. Anchored, no prompt: an open / close mechanic can
--                       tween the model's pivot between ClosedCF and OpenCF later.
--     Visuals           the modeler's meshes (ServerStorage.HouseKit): Shell (in place), Furniture (on its COLP box), Dressing.
--                       Never collide / query / touch.
--     Lights            invisible holders with the room lights.
--     MatchSpawns       SpawnA (living room) / SpawnB (kitchen): RoundManager points Workspace.MatchSpawns at them.
--   Workspace.HouseExterior (Indoor = false): the street, the houses across, yards: seen through the windows, unreachable.
--   ReplicatedStorage.DuelMaps.House: the registry entry (modes 1v1 / 2v2 / 3v3, own Lighting).
--   BotConfig.CoverFolders += "House/CollisionProxies".
--   ServerScriptService.HouseBounds: the backstop return volume (a body that leaves the house box by walking, or falls, is put
--     back where it last stood inside).
-- Idempotent: each run rebuilds all of it. A House it didn't build goes to ServerStorage._House_Backup (never deleted).
-- UNDO = true removes House, HouseExterior, the registry entry, HouseBounds and the BotConfig line.
local UNDO = false --@UNDO
local ORIGIN = Vector3.new(-650, 1.2, -450) -- plan (0, 0, 0) = house centre at ground-floor top; clear of every other map;
-- 1.2 up so the exterior ground (plan z -1) clears the place's Baseplate top (y 0)
local MAP_NAME, EXT_NAME, REG_ID, KIT_NAME = "House", "HouseExterior", "House", "HouseKit"
local SHELL_YAW = math.pi -- the shell FBX is in plan coordinates; Import 3D maps Blender (x, y, z) to Studio (-x, z, y)
--@@LAYOUT

local RS = game:GetService("ReplicatedStorage")
local SS = game:GetService("ServerStorage")
local SSS = game:GetService("ServerScriptService")
local CS = game:GetService("CollectionService")
local M = Enum.Material
local function rgb(r, g, b) return Color3.fromRGB(r, g, b) end

if SS:FindFirstChild("_DuelSource") then
	return "map_house: this is the lobby (ServerStorage._DuelSource): House is built in the match places; the lobby gets it through duel_split_map"
end

-- ====================================================================================================== BotConfig line
local function findModule(name)
	for _, d in game:GetDescendants() do
		if d:IsA("ModuleScript") and d.Name == name and not d:FindFirstAncestorWhichIsA("Model") then
			local ok, path = pcall(function() return d:GetFullName() end)
			if ok and not path:find("_Backup") and not path:find("_Orig") then return d end
		end
	end
end
local BOT_ADD = ', "House/CollisionProxies"'
local function botConfig(add)
	local bc = findModule("BotConfig")
	if not bc then return "no BotConfig" end
	local src = bc.Source
	local has = src:find(BOT_ADD, 1, true) ~= nil
	if add and not has then
		local a, b = src:find("CoverFolders%s*=%s*{[^}]*")
		if not a then return "BotConfig: no CoverFolders line" end
		local head = src:sub(1, b):gsub("%s+$", "")
		bc.Source = head .. BOT_ADD .. " " .. src:sub(b + 1):gsub("^%s+", "")
		return "BotConfig += House"
	elseif not add and has then
		bc.Source = src:gsub(BOT_ADD:gsub("%p", "%%%0") .. " ?", "", 1)
		return "BotConfig -= House"
	end
	return "BotConfig ="
end

-- ====================================================================================================== undo / backup
local old, oldExt = workspace:FindFirstChild(MAP_NAME), workspace:FindFirstChild(EXT_NAME)
local reg = RS:FindFirstChild("DuelMaps")
local entry0 = reg and reg:FindFirstChild(REG_ID)
local bounds0 = SSS:FindFirstChild("HouseBounds")
if UNDO then
	if old and old:GetAttribute("Builder") == "map_house" then old:Destroy() end
	if oldExt and oldExt:GetAttribute("Builder") == "map_house" then oldExt:Destroy() end
	if entry0 then entry0:Destroy() end
	if bounds0 then bounds0:Destroy() end
	return "UNDO: House, HouseExterior, DuelMaps.House, HouseBounds removed; " .. botConfig(false)
end
for _, m in { old, oldExt } do
	if m and m:GetAttribute("Builder") ~= "map_house" then
		local bk = SS:FindFirstChild("_House_Backup") or Instance.new("Folder")
		bk.Name = "_House_Backup"; bk.Parent = SS
		m.Name = m.Name .. "_" .. os.time(); m.Parent = bk
	elseif m then
		m:Destroy()
	end
end
if entry0 then entry0:Destroy() end
if bounds0 then bounds0:Destroy() end
assert(reg, "map_house: no ReplicatedStorage.DuelMaps (not a match place?)")

-- ====================================================================================================== helpers
local function W(x, y, z) return ORIGIN + Vector3.new(x, z, -y) end -- plan (x east, y north, z up) -> world
local DIR = { S = Vector3.new(0, 0, 1), N = Vector3.new(0, 0, -1), E = Vector3.new(1, 0, 0), W = Vector3.new(-1, 0, 0) }
local map = Instance.new("Model"); map.Name = MAP_NAME
local ext = Instance.new("Model"); ext.Name = EXT_NAME
local function folder(name, parent) local f = Instance.new("Folder") f.Name = name f.Parent = parent return f end
local CP = folder("CollisionProxies", map)
local SH = folder("Shootables", map)
local DO = folder("Doors", map)
local VIS = Instance.new("Model"); VIS.Name = "Visuals"; VIS.Parent = map
local VSH = folder("Shell", VIS); local VFU = folder("Furniture", VIS); local VDR = folder("Dressing", VIS)
local LI = folder("Lights", map)
local SP = folder("MatchSpawns", map)
local nProxy, nArt, nLights = 0, 0, 0

local ROLE_MAT = { wall = M.Concrete, sill = M.Concrete, floor = M.WoodPlanks, ceiling = M.Concrete, stair = M.WoodPlanks,
	rail = M.Metal, door = M.Wood, barrier = M.SmoothPlastic, blocker = M.SmoothPlastic }
local MODEL_MAT = { Fabric = { "Sofa", "Armchair", "Bed", "Headboard", "Bench", "Beanbag" }, Metal = { "Fridge", "Oven" },
	Marble = { "Kitchen", "Bathtub", "Vanity" }, Glass = { "Shower" } }
local function matFor(p)
	if p.role ~= "furniture" then return ROLE_MAT[p.role] or M.Concrete end
	for mat, keys in MODEL_MAT do
		for _, k in keys do if (p.model or ""):find(k) then return M[mat] end end
	end
	return M.Wood
end

local function invisible(p)
	p.Anchored = true
	p.Transparency = 1
	p.CastShadow = false
	p.Locked = true
end

local function proxyBox(p)
	local part = Instance.new("Part")
	local name = p.role == "barrier" and ("BAR_" .. p.id:gsub("^Bar_", "")) or (p.role == "blocker" and p.id or ("COLP_" .. p.id))
	part.Name = name
	part.Size = Vector3.new(p.x1 - p.x0, p.z1 - p.z0, p.y1 - p.y0)
	part.CFrame = CFrame.new(W((p.x0 + p.x1) / 2, (p.y0 + p.y1) / 2, (p.z0 + p.z1) / 2))
	return part
end

local wedgeFlip -- found once: which end of a WedgePart is high (engine geometry, tested by raycast)
local function rampPart(p)
	local part = Instance.new("WedgePart")
	part.Name = "COLP_" .. p.id
	local run = math.abs(p.y1 - p.y0)
	part.Size = Vector3.new(p.x1 - p.x0, p.z1 - p.z0, run)
	-- high end toward the plan top_y. World: plan +y = -Z. Face the part so its high end is toward W(top) - W(foot).
	local cx, cy, cz = (p.x0 + p.x1) / 2, (p.y0 + p.y1) / 2, (p.z0 + p.z1) / 2
	local toTop = (W(cx, p.top_y, cz) - W(cx, p.foot_y, cz)).Unit
	if wedgeFlip == nil then
		local t = Instance.new("WedgePart"); t.Size = Vector3.new(4, 4, 4); t.Anchored = true
		t.CFrame = CFrame.new(0, 5000, 0); t.Parent = workspace
		local rp = RaycastParams.new(); rp.FilterType = Enum.RaycastFilterType.Include; rp.FilterDescendantsInstances = { t }
		local hA = workspace:Raycast(Vector3.new(0, 5010, 1.5), Vector3.new(0, -20, 0), rp)
		local hB = workspace:Raycast(Vector3.new(0, 5010, -1.5), Vector3.new(0, -20, 0), rp)
		-- high end at local -Z if the ray at -1.5 hits higher
		wedgeFlip = (hB and hB.Position.Y or 0) > (hA and hA.Position.Y or 0) -- true: high end = local -Z
		t:Destroy()
	end
	local look = wedgeFlip and toTop or -toTop -- LookVector (-Z) points to the high end when wedgeFlip
	local c = W(cx, cy, cz)
	part.CFrame = CFrame.lookAt(c, c + look)
	return part
end

local function oboxPart(p)
	local part = Instance.new("Part")
	part.Name = "Leaf"
	part.Size = Vector3.new(p.w, p.z1 - p.z0, p.d)
	part.CFrame = CFrame.new(W(p.cx, p.cy, (p.z0 + p.z1) / 2)) * CFrame.Angles(0, math.rad(p.yaw), 0)
	return part
end

local function setGameplay(part, p)
	invisible(part)
	part.Material = matFor(p)
	part.CanCollide, part.CanTouch = true, true
	part.CanQuery = true
	local cover = (p.role == "furniture" and (p.cover == "low" or p.cover == "tall")) or (p.role == "sill" and p.id:find("Pass_"))
	if not cover then part:SetAttribute("NotCover", true) end
	if p.role == "barrier" or p.role == "blocker" then
		part.CanTouch = false
		part.CanQuery = false
		CS:AddTag(part, "WindowBarrier")
		part:SetAttribute("NotCover", true)
	end
	part:SetAttribute("Role", p.role)
	if p.cover and p.cover ~= "none" then part:SetAttribute("Cover", p.cover) end
	if p.model then part:SetAttribute("Model", p.model) end
	nProxy += 1
end

-- ====================================================================================================== gameplay layer
local leafById = {}
for _, p in L.parts do
	local part
	if p.shape == "box" then part = proxyBox(p)
	elseif p.shape == "ramp" then part = rampPart(p)
	elseif p.shape == "obox" then part = oboxPart(p) leafById[p.id:gsub("_Leaf$", "")] = part
	end
	setGameplay(part, p)
	part:SetAttribute("PartId", p.id)
	if p.shape ~= "obox" then part.Parent = CP end
end
-- planned drops (MapAudit HOLE): the landing / upper-hall slabs end at the foyer void and the back stair well; the edges are
-- closed by the gallery railing + its player barrier, and the stair wells by walls / banister barriers (enclosure proof:
-- tools/house_check.py flood on the read-back, 0 cells outside, with a door-open control that leaks)
for _, id in { "Slab_LD", "Slab_UH", "Slab_ST2End", "Slab_W", "Slab_E", "Stair_Main_Ramp", "Stair_Back_Ramp" } do
	local p = CP:FindFirstChild("COLP_" .. id)
	if p then CS:AddTag(p, "KitIntendedDrop"); p:SetAttribute("DropReason", "edge of the foyer void / a stair well, behind a railing barrier or wall") end
end

-- doors: real hinged doors, held as the layout says (ajar 70 degrees / closed / locked), anchored, no prompt
for _, d in L.doors do
	local m = Instance.new("Model"); m.Name = d.id; m.Parent = DO
	local hinge = Instance.new("Part"); hinge.Name = "Hinge"; hinge.Size = Vector3.new(0.3, d.leaf.h, 0.3)
	local hx, hy = d.hinge[1], d.hinge[2]
	-- the hinge part's own frame: X along the leaf (closed direction when shut), Y up; ajar = turned by angle about Y
	local closedYaw = math.atan2(d.closed_dir[2], d.closed_dir[1])
	local base = CFrame.new(W(hx, hy, d.z0 + d.leaf.h / 2))
	local closedCF = base * CFrame.Angles(0, closedYaw, 0)
	local openYawPlan = math.rad(d.leaf_yaw_deg)
	local heldCF = base * CFrame.Angles(0, openYawPlan, 0)
	-- the open pose for a door shown shut is the ajar pose (AJAR_DEG toward its swing side)
	local sgn = (d.open_dir_side[1] * -d.closed_dir[2] + d.open_dir_side[2] * d.closed_dir[1]) >= 0 and 1 or -1
	local openCF = base * CFrame.Angles(0, closedYaw + sgn * math.rad(d.open_deg), 0)
	hinge.CFrame = heldCF
	invisible(hinge); hinge.CanCollide, hinge.CanQuery, hinge.CanTouch = false, false, false
	hinge.Parent = m
	m.PrimaryPart = hinge
	local leaf = leafById[d.id]
	leaf.Parent = m
	leaf:SetAttribute("NotCover", true)
	m:SetAttribute("DoorState", d.state == "Ajar" and "Open" or d.state)
	m:SetAttribute("Ajar", d.state == "Ajar")
	m:SetAttribute("OpenDeg", d.open_deg)
	m:SetAttribute("Locked", d.locked == true)
	m:SetAttribute("ClosedCF", closedCF)
	m:SetAttribute("OpenCF", openCF)
	m:SetAttribute("Model", d.model)
	CS:AddTag(m, "HouseDoor")
end

-- spawns: one marker per team; teammates line up 4 apart along the marker's right vector (RoundManager)
for team, s in L.spawns do
	local at = W(s.x, s.y, s.z + 0.5)
	local m = Instance.new("Part"); m.Name = "Spawn" .. team; m.Size = Vector3.new(4, 1, 4)
	m.CFrame = CFrame.lookAt(at, at + Vector3.new(s.look[1], 0, -s.look[2]))
	invisible(m); m.CanCollide, m.CanQuery, m.CanTouch = false, false, false
	m.Color = team == "A" and rgb(255, 90, 90) or rgb(80, 160, 255)
	m.Parent = SP
end

-- ====================================================================================================== art (the modeler's kit)
local KIT = SS:FindFirstChild(KIT_NAME)
local skipped, nMesh = {}, 0
local function artFlags(inst)
	for _, d in (inst:IsA("BasePart") and { inst } or {}) do d.Anchored, d.CanCollide, d.CanQuery, d.CanTouch = true, false, false, false end
	for _, d in inst:GetDescendants() do
		if d:IsA("BasePart") then d.Anchored, d.CanCollide, d.CanQuery, d.CanTouch = true, false, false, false; nArt += 1 end
	end
end
local function asModel(src)
	local c = src:Clone()
	if c:IsA("BasePart") then local h = Instance.new("Model") h.Name = src.Name c.Parent = h return h end
	return c
end
local ART_ABOVE = { H_TVConsole_WithTV = true, H_Planter = true, H_Bathtub = true }
-- place a kit model with its bounding box's bottom centre on plan (x, y, z), its front (local -Z) toward `face`
local function placeKit(name, parent, x, y, z, face, fit, label)
	local src = KIT and KIT:FindFirstChild(name)
	if not src then table.insert(skipped, (label or name) .. ": no " .. name) return nil end
	local m = asModel(src)
	m.Name = label or name
	m:SetAttribute("KitModel", name)
	m.Parent = parent
	local cf, size = m:GetBoundingBox()
	local bottom = cf * CFrame.new(0, -size.Y / 2, 0)
	local at = W(x, y, z)
	local target = CFrame.lookAt(at, at + DIR[face or "S"])
	m:PivotTo(target * bottom:ToObjectSpace(m:GetPivot()))
	artFlags(m)
	if fit then
		local _, s2 = m:GetBoundingBox()
		local want = Vector3.new(fit[1], fit[3], fit[2]) -- plan box (dx, dy, dz) -> world (X, Y, Z)
		-- GetBoundingBox is in the model's own axes (= the target turn): a piece facing E / W lies across
		local w, d = s2.X, s2.Z
		if face == "E" or face == "W" then w, d = s2.Z, s2.X end
		local tallArt = ART_ABOVE[name] == true -- art meant to rise above its collision box (the TV, the plant)
		if math.abs(w - want.X) > 0.3 or math.abs(d - want.Z) > 0.3 or (not tallArt and math.abs(s2.Y - want.Y) > 0.3) then
			table.insert(skipped, ("%s: %s is %.2f x %.2f x %.2f, box %.2f x %.2f x %.2f (placed anyway)"):format(label or name, name, s2.X, s2.Y, s2.Z, want.X, want.Y, want.Z))
		end
	end
	nMesh += 1
	return m
end

-- the shell: one model in plan coordinates (the modeler built it on the layout's boxes); doors and windows are taken out of it
local shell
if KIT and KIT:FindFirstChild("H_House") then
	shell = asModel(KIT.H_House)
	shell.Name = "Shell"
	shell.Parent = VIS
	shell:PivotTo(CFrame.new(ORIGIN) * CFrame.Angles(0, SHELL_YAW, 0))
	artFlags(shell)
	VSH:Destroy(); VSH = shell
	nMesh += 1
else
	table.insert(skipped, "shell: no " .. KIT_NAME .. ".H_House")
end
local function takeFromShell(name)
	if not shell then return nil end
	return shell:FindFirstChild(name, true)
end

-- windows: Shootables.<id> = Model { Glass, BrokenGlass } (Shootable = "Glass"); the frame stays in the shell
local nWin = 0
for _, w in L.windows do
	local m = Instance.new("Model"); m.Name = w.id
	m:SetAttribute("Shootable", "Glass")
	m:SetAttribute("Window", w.id)
	local glass, broken = takeFromShell(w.id .. "_Glass"), takeFromShell(w.id .. "_BrokenGlass")
	if glass then
		glass.Name = "Glass"; glass.Parent = m
		for _, g in (glass:IsA("BasePart") and { glass } or glass:GetDescendants()) do
			if g:IsA("BasePart") then g.CastShadow = false; g.CanQuery = true end -- queryable at authoring so the lobby split keeps a Solid twin; the game turns it off
		end
	end
	if broken then broken.Name = "BrokenGlass"; broken.Parent = m end
	if not glass then table.insert(skipped, w.id .. ": no glass mesh") end
	m.Parent = SH
	nWin += 1
end
-- doors: the leaf meshes (posed at the held angle in the shell, origin on the hinge) move into their door models
for _, d in L.doors do
	local dm = DO:FindFirstChild(d.id)
	for _, nm in { d.id, d.id .. "_Glass", d.id .. "_BrokenGlass" } do
		local a = takeFromShell(nm)
		if a then a.Parent = dm end
	end
	if not takeFromShell(d.id) and not dm:FindFirstChild(d.id) then table.insert(skipped, d.id .. ": no leaf mesh") end
	-- a door's broken pane is not a Shootables window (the game never hides it): hidden here, kept for a later door mechanic
	local bg = dm:FindFirstChild(d.id .. "_BrokenGlass")
	for _, x in (bg and (bg:IsA("BasePart") and { bg } or bg:GetDescendants()) or {}) do if x:IsA("BasePart") then x.Transparency = 1 end end
end

-- furniture: each on its COLP box; composites (kitchen runs, two dining sets) are laid out along the box's long side
local RUN = { KitchenRun1 = { "H_KitchenBase" }, KitchenRun3 = { "H_KitchenBase", "H_KitchenSink", "H_KitchenBase" },
	KitchenRun6 = { "H_KitchenBase", "H_KitchenSink", "H_KitchenBase", "H_KitchenHob", "H_KitchenBase", "H_KitchenBase" } }
for _, f in L.furniture do
	local cx, cy = (f.x0 + f.x1) / 2, (f.y0 + f.y1) / 2
	local fit = { f.x1 - f.x0, f.y1 - f.y0, f.z1 - f.z0 }
	local face = f.face
	if not face then face = (fit[1] >= fit[2]) and "S" or "E" end
	local runs = RUN[f.model]
	if runs and f.id == "LR_Sideboard" then runs = { "H_KitchenBase", "H_KitchenBase", "H_KitchenBase" } end
	if runs then
		local alongX = (fit[1] >= fit[2])
		local n = #runs
		for k, nm in runs do
			local t = (k - 0.5) / n
			local x = alongX and (f.x0 + (f.x1 - f.x0) * t) or cx
			local y = alongX and cy or (f.y0 + (f.y1 - f.y0) * t)
			placeKit(nm, VFU, x, y, f.z0, face, nil, f.id .. "_" .. k)
		end
	elseif f.model == "H_DiningSet" then
		placeKit("H_DiningSet", VFU, f.x0 + (f.x1 - f.x0) * 0.25, cy, f.z0, face or "S", nil, f.id .. "_1")
		placeKit("H_DiningSet", VFU, f.x0 + (f.x1 - f.x0) * 0.75, cy, f.z0, face or "S", nil, f.id .. "_2")
	else
		placeKit(f.model, VFU, cx, cy, f.z0, face, fit, f.id)
	end
end
-- dressing (art only; the floor pieces have their PCOL blockers in CollisionProxies)
for _, d in L.dressing do
	if d.model == "H_PendantLamp" then
		local m = placeKit(d.model, VDR, d.x, d.y, d.z - d.size[2], d.face, nil, d.id)
	else
		placeKit(d.model, VDR, d.x, d.y, d.z, d.face, nil, d.id)
	end
end

-- ====================================================================================================== lights
-- room downlights: an invisible holder at the ceiling with a downward SpotLight (pool) and a weak PointLight fill; the lamps
-- (floor / table / pendant) get a warm PointLight. Values = the brief's lighting; tuned on the render at quality 21.
local function holder(name, x, y, z)
	local h = Instance.new("Part"); h.Name = name; h.Size = Vector3.new(0.4, 0.4, 0.4)
	h.CFrame = CFrame.lookAt(W(x, y, z), W(x, y, z - 1))
	invisible(h); h.CanCollide, h.CanQuery, h.CanTouch = false, false, false
	h.Parent = LI
	return h
end
for _, l in L.lights do
	local h = holder(l.id, l.x, l.y, l.z)
	if l.kind == "down" then
		local s = Instance.new("SpotLight"); s.Face = Enum.NormalId.Front; s.Angle = l.angle; s.Range = l.range
		s.Brightness = l.bright; s.Color = rgb(table.unpack(l.color)); s.Shadows = l.shadows; s.Parent = h
		nLights += 1
		if l.fill and l.fill > 0 then
			local p = Instance.new("PointLight"); p.Range = l.range * 0.9; p.Brightness = l.fill; p.Color = rgb(table.unpack(l.color))
			p.Shadows = false; p.Parent = h
			nLights += 1
		end
	else
		local p = Instance.new("PointLight"); p.Range = l.range; p.Brightness = l.bright; p.Color = rgb(table.unpack(l.color))
		p.Shadows = l.shadows; p.Parent = h
		nLights += 1
	end
end

-- ====================================================================================================== exterior (seen only)
if KIT and KIT:FindFirstChild("H_Exterior") then
	local e = asModel(KIT.H_Exterior)
	e.Name = "Set"; e.Parent = ext
	e:PivotTo(CFrame.new(ORIGIN) * CFrame.Angles(0, SHELL_YAW, 0))
	artFlags(e)
	nMesh += 1
	-- the modeler's realistic trees + trimmed hedge (Edward 2026-10-28: "better trees and outside") replace the faceted blobs
	if KIT:FindFirstChild("H_Trees") then
		for _, d in e:GetDescendants() do
			if d:IsA("BasePart") and (d.Name:match("^Tree_%d+$") or d.Name:match("^Tree_%d+_Leaves") or d.Name == "Ext_Yard_Hedge") then d:Destroy() end
		end
		local t = asModel(KIT.H_Trees)
		t.Name = "Trees"; t.Parent = ext
		t:PivotTo(CFrame.new(ORIGIN) * CFrame.Angles(0, SHELL_YAW, 0))
		artFlags(t)
		-- two trees stood inside the houses behind (trunks at plan y 92, houses y 90..126): into their back gardens, plan y -9
		for _, d in t:GetDescendants() do
			if d:IsA("BasePart") and (d.Name:match("^Tree_1[45]$") or d.Name:match("^Tree_1[45]_Crown")) then d.CFrame = d.CFrame + Vector3.new(0, 0, 9) end
		end
		nMesh += 1
	end
else
	table.insert(skipped, "exterior: no " .. KIT_NAME .. ".H_Exterior")
end


-- ====================================================================================================== plain colours
-- Import 3D brings the baked atlases (SurfaceAppearance) and tiling textures but not plain material colours: the modeler's
-- build scripts' values (art/house/tools/build_exterior.py PLAIN_COL / PLAIN_KIND, build_house.py) are applied by name here.
local FROSTED = {}
for _, w in L.windows do if w.frosted then FROSTED[w.id] = true end end
local PLAIN = { Paint = { 232, 226, 210 }, FencePost = { 48, 46, 44 }, GlassDark = { 40, 46, 50 }, Frame = { 44, 44, 44 },
	GarageDoor = { 196, 196, 192 }, DoorOak = { 150, 112, 76 }, Charcoal = { 44, 44, 44 }, SidingWhite = { 226, 224, 218 },
	RoofTile = { 84, 80, 78 }, Pole = { 96, 78, 60 }, Pole2 = { 30, 30, 31 }, Wire = { 20, 20, 20 }, Mailbox = { 30, 30, 31 },
	Leaves = { 64, 96, 54 }, LeavesDark = { 44, 72, 44 } }
local nPlain = 0
local function plainOf(part)
	if part:FindFirstChildOfClass("SurfaceAppearance") or (part:IsA("MeshPart") and part.TextureID ~= "") then return end
	local n = part.Name
	local win = n:match("^(Win_.-)_Glass$") or n:match("^(Win_.-)_BrokenGlass$")
	local function glass(frost)
		part.Material = M.Glass
		part.Color = frost and rgb(214, 222, 226) or rgb(150, 170, 180)
		part.Transparency = frost and 0.3 or 0.82
		part.Reflectance = 0.06
		part.CastShadow = false
	end
	if n == "Glass" or n == "BrokenGlass" then
		local w = part:FindFirstAncestorWhichIsA("Model")
		glass(w and FROSTED[w.Name])
	elseif win then glass(FROSTED[win])
	elseif n:match("Glow$") then part.Material = M.Neon; part.Color = rgb(255, 250, 236); part.CastShadow = false
	elseif n:match("Glass$") then glass(false)
	elseif n:match("^Tree_%d+$") then part.Color = rgb(92, 70, 52)
	else
		local key = n:match("_([%a%d]+)$") or n
		local c = PLAIN[key] or PLAIN[n]
		if c then part.Color = rgb(table.unpack(c)) else return end
		if key == "GlassDark" then part.Material = M.Glass; part.Reflectance = 0.15 end
	end
	nPlain += 1
end
for _, root in { map, ext } do
	for _, d in root:GetDescendants() do if d:IsA("BasePart") and (d:FindFirstAncestor("Visuals") or d:FindFirstAncestor("Shootables") or d:FindFirstAncestor("Doors") or root == ext) and d.Transparency < 1 then plainOf(d) end end
end
-- the tall cabinets read as fridges (white with a long handle): a warm oak tint on their atlas (Edward 2026-10-28)
for _, m in VFU:GetChildren() do
	for _, d in m:GetDescendants() do
		if d:IsA("SurfaceAppearance") and m:GetAttribute("KitModel") == "H_TallCabinet" then d.Color = rgb(214, 172, 128) end
	end
end
-- the mirrors: the baked atlas of a mirror is black (a diffuse bake of a metal): a pale, slightly reflective pane instead
for _, m in VDR:GetChildren() do
	if m.Name:match("_Mirror$") then
		for _, d in m:GetDescendants() do
			if d:IsA("SurfaceAppearance") then d:Destroy() end
			if d:IsA("BasePart") then d.Material = M.Glass; d.Color = rgb(196, 204, 208); d.Reflectance = 0.35; d.Transparency = 0 end
		end
	end
end
-- the shower screens' glass (baked atlas, opaque): see-through as the modeler intended (Transparency 0.7)
for _, d in VIS:GetDescendants() do
	if d:IsA("BasePart") and d.Parent and d.Parent.Name:match("ShowerGlass") and d.Name:match("Glass") then d.Transparency = 0.7 end
end

