-- ====================================================================================================== backstop
local bs = Instance.new("Script")
bs.Name = "HouseBounds"
bs.Source = ([[
-- HouseBounds [HOUSE] (fix/map_house.lua): the House's backstop return volume. The window barriers, walls and locked doors
-- are the real enclosure; if a body ever ends up outside the house box (or below the floor) right after standing inside it
-- (a short move, not a teleport), it is put back where it last stood inside. Other maps and the after-match lobby are never
-- touched: a body that was not inside the house in the last moment, or jumped far (a teleport), is ignored.
local Players = game:GetService("Players")
local ORIGIN = Vector3.new(%.3f, %.3f, %.3f)
local HALF = Vector3.new(%.2f, 0, %.2f)      -- the house box, inside faces + a margin
local LOW, HIGH = ORIGIN.Y - 3, ORIGIN.Y + 30
local last = {}
local function inside(p)
	local d = p - ORIGIN
	return math.abs(d.X) <= HALF.X and math.abs(d.Z) <= HALF.Z and p.Y >= LOW and p.Y <= HIGH
end
while true do
	task.wait(0.2)
	for _, plr in Players:GetPlayers() do
		local c = plr.Character
		local root = c and c:FindFirstChild("HumanoidRootPart")
		local hum = c and c:FindFirstChildOfClass("Humanoid")
		if root and hum and hum.Health > 0 then
			local p = root.Position
			if inside(p) then
				if hum.FloorMaterial ~= Enum.Material.Air then last[c] = root.CFrame end
			elseif last[c] then
				if (p - last[c].Position).Magnitude < 25 then
					root.AssemblyLinearVelocity = Vector3.zero
					c:PivotTo(last[c])
				else
					last[c] = nil -- a teleport (round reset, after-match lobby): not an escape
				end
			end
		end
	end
	for c in last do if not c.Parent then last[c] = nil end end
end
]]):format(ORIGIN.X, ORIGIN.Y, ORIGIN.Z, L.shell.x1 + 2, L.shell.y1 + 2)
bs.Parent = SSS

